    if n < 6:
        if last_opp == 'D' and last_me == 'C':
            return 'D'
        return 'C'

    recent_k = 10 if n >= 10 else n
    recent_opp = opp[-recent_k:]
    recent_me = me[-recent_k:]
    recent_opp_c = sum(1 for x in recent_opp if x == 'C')
    recent_opp_d = recent_k - recent_opp_c
    recent_opp_rate = recent_opp_c / float(recent_k)

    # Estimate opponent responsiveness: did opponent defect right after our defections?
    punish_count = 0
    punish_opp_d = 0
    for i in range(1, n):
        if me[i-1] == 'D':
            punish_count += 1
            if opp[i] == 'D':
                punish_opp_d += 1
    responsive = False
    if punish_count >= 3:
        responsive = punish_opp_d / float(punish_count) >= 0.55

    # Detect sustained defector: defect almost always, but probe rarely.
    if n >= 15 and opp_d >= n - 2:
        if opp_c >= 2 and recent_opp_rate > 0.1:
