        # Rare probe against pure cooperators.
        if opp_d == 0 and n >= 30 and n % 11 == 0:
            return 'D' if rng.random() < 0.25 else 'C'
        return 'C'

    # Strong recent cooperation: maintain it, with occasional testing only
