                return 'D'
        return 'C'

    if recent_d >= 5:
        return 'D' if rng.random() < 0.9 else 'C'

    coop_rate = opp_c / n

    if coop_rate > 0.8:
        if last_opp == 'D':
            return 'C' if rng.random() < 0.45 else 'D'
        if recent_d <= 1:
            return 'C'
        if rng.random() < 0.25:
