    if consec >= 3:
        # If we've already retaliated several times, mix in forgiveness
        own_consec_d = 0
        for i in range(n - 1, -1, -1):
            if own[i] == 'D':
                own_consec_d += 1
            else:
                break
        if own_consec_d >= 3 and rng.random() < 0.2:
            return 'C'
        return 'D'

    if last_opp == 'D':
