    if n == 0:
        return 'C'
    if n == 1:
        return 'C' if history[0][1] == 'C' else 'D'

    opp = [h[1] for h in history]
    me = [h[0] for h in history]
    opp_last = opp[n - 1]

    # Count defections in recent window
    w = min(10, n)
    rd = 0
    for i in range(n - w, n):
        if opp[i] == 'D':
            rd += 1

    total_opp_c = 0
    for x in opp:
        if x == 'C':
            total_opp_c += 1
    total_opp_d = n - total_opp_c

    # Always defecting opponent
    if total_opp_d == n:
        return 'D'

    # Always cooperating opponent: exploit in endgame only
    if total_opp_c == n:
        if n >= 94:
            return 'D'
        return 'C'

    # Detect TFT-like: opponent mirrors my previous action
    if n >= 8:
        matches = 0
        for i in range(1, n):
            if opp[i] == me[i - 1]:
