def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C'

    opp = [h[1] for h in history]
    me = [h[0] for h in history]
    last_me, last_opp = history[-1]
    opp_c = opp.count('C')
    opp_d = n - opp_c
    recent = opp[-8:]
    recent_d = recent.count('D')
    recent_c = len(recent) - recent_d

    if n >= 90:
        if opp_d * 4 <= n:
            return 'C'
        if recent_d >= 2:
            return 'D'
        return 'C'

    if opp_d == 0:
        if n >= 88:
            return 'D'
        if n >= 25 and n % 13 == 12 and rng.random() < 0.25:
            return 'D'
        return 'C'

    if recent_d == 0:
        if last_me == 'D':
            return 'C'
        if n >= 20 and opp_c == n and n % 17 == 16:
            return 'D'
        return 'C'

    if recent_d >= 5:
        return 'D'

    if last_opp == 'D':
        if last_me == 'D':
            run = 0
            for a in reversed(opp):
                if a == 'D':
                    run += 1
                else:
                    break
            if run >= 3:
                if rng.random() < 0.3:
                    return 'C'
                return 'D'
            if opp_c >= n // 2:
                return 'D'
            if rng.random() < 0.25:
                return 'C'
            return 'D'
        else:
            d_recent = recent_d
            if d_recent >= 3:
                return 'D'
            if rng.random() < 0.15:
                return 'C'
            return 'D'

    if last_opp == 'C':
        if last_me == 'D':
            return 'C'
        run_c = 0
        for a in reversed(opp):
            if a == 'C':
                run_c += 1
            else:
                break
        if run_c >= 6 and n >= 20:
            if rng.random() < 0.12:
                return 'D'
        if n >= 60 and opp_d * 5 <= n:
            if rng.random() < 0.08:
                return 'D'
        return 'C'

    return 'C'

