        if a == 'C':
            my_c += 1
            if b == 'C':
                cc += 1
            else:
                pass
        else:
            my_d += 1
        if b == 'C':
            opp_c += 1
        else:
            opp_d += 1

    # Recent window stats.
    w = 8 if n >= 8 else n
    rec_opp_d = 0
    rec_my_d = 0
    rec_cc = 0
    for i in range(n - w, n):
        a, b = history[i]
        if b == 'D':
            rec_opp_d += 1
        if a == 'D':
            rec_my_d += 1
        if a == 'C' and b == 'C':
            rec_cc += 1

    last_my, last_opp = history[-1]
    remaining = 100 - n

    # Opponent never defected: exploit, but keep some cooperation to avoid
