def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C'

    def opp_at(i):
        return history[i][1]

    def me_at(i):
        return history[i][0]

    c_opp = 0
    for i in range(n):
        if opp_at(i) == 'C':
            c_opp += 1

    # Always cooperate against always-cooperator
    if c_opp == n:
        if n >= 96:
            return 'D'
        return 'C'

    # Always defect against always-defector
    if c_opp == 0:
        return 'D'

    coop_rate = c_opp / n
    last = opp_at(n - 1)

    # Count trailing defection streak
    streak_d = 0
    i = n - 1
    while i >= 0 and opp_at(i) == 'D':
        streak_d += 1
        i -= 1

    # Count trailing cooperation streak
    streak_c = 0
    i = n - 1
    while i >= 0 and opp_at(i) == 'C':
        streak_c += 1
        i -= 1

    # Detect TFT-like: opponent copies our previous move
    if n >= 8:
        matches = 0
        total = n - 1
        for i in range(1, n):
            if opp_at(i) == me_at(i - 1):
                matches += 1
        if matches >= total * 0.85:
            if n >= 97:
                return 'D'
            return me_at(n - 1)

    # Detect alternating opponent
    if n >= 6:
        flips = 0
        for i in range(1, n):
            if opp_at(i) != opp_at(i - 1):
                flips += 1
        if flips >= n - 2:
            if last == 'C':
                return 'D'
            return 'C'

    # Endgame exploitation
    remaining = 100 - n
    if remaining <= 3:
        if coop_rate > 0.5:
            return 'D'
        return 'C'

    # Strong punishment for long defection streaks
    if streak_d >= 2:
        if coop_rate >= 0.75 and streak_d <= 3:
            return 'C'
        return 'D'

    # Forgive isolated defections if opponent generally cooperative
    if streak_d == 1:
        if coop_rate >= 0.7 and streak_c >= 2:
            return 'C'
        if n >= 4 and opp_at(n - 3) == 'C' and opp_at(n - 4) == 'C':
            return 'C'
        return 'D'

    # After opponent cooperated
    if coop_rate >= 0.85:
        if n >= 5 and n % 11 == 0 and streak_c >= 3:
            return 'D'
        return 'C'

    if coop_rate >= 0.6:
        if streak_c >= 2:
            if rng.random() < 0.05:
                return 'D'
            return 'C'
        if rng.random() < 0.15:
            return 'D'
        return 'C'

    if coop_rate >= 0.4:
        if rng.random() < 0.4:
            return 'D'
        return 'C'

    return 'D'

