    opp_def_5 = 0
    for i in range(n - 1, -1, -1):
        if n - i <= 10:
            if history[i][1] == 'D':
                opp_def_10 += 1
            if history[i][0] == 'D':
                my_def_10 += 1
        if n - i <= 5:
            if history[i][1] == 'D':
                opp_def_5 += 1
        if n - i > 10:
            break

