def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C'

    me = [h[0] for h in history]
    opp = [h[1] for h in history]
    last_me = me[-1]
    last_opp = opp[-1]

    opp_c = opp.count('C')
    opp_d = n - opp_c

    if n >= 10:
        recent_d = opp[-10:].count('D')
        if recent_d >= 8:
            return 'D'

    if n >= 95:
        if opp_d >= 3:
            return 'D'
        return 'C'

    if n >= 2 and last_opp == 'D' and opp[-2] == 'D':
        recent_opp_d = opp[-6:].count('D') if n >= 6 else opp_d
        if recent_opp_d >= 3:
            return 'D'

    if n >= 4 and opp[-4:].count('D') >= 3:
        if rng.random() < 0.75:
            return 'D'

    if last_opp == 'D':
        if last_me == 'D':
            if n >= 8 and opp[-8:].count('D') >= 5:
                return 'D'
            if rng.random() < 0.2:
                return 'C'
            return 'D'
        else:
            if opp_d >= 12 and opp_c >= 12:
                return 'D'
            if rng.random() < 0.15:
                return 'D'
            return 'C'

    if last_opp == 'C':
        if last_me == 'D':
            return 'C'
        run_c = 0
        for a in reversed(opp):
            if a == 'C':
                run_c += 1
            else:
                break
        if run_c >= 4 and n >= 15:
            if rng.random() < 0.12:
                return 'D'
        return 'C'

    return 'C'

