        if n >= 6:
            my_recent_def = 0
            for a in me[-6:]:
                if a == 'D':
                    my_recent_def += 1
            if my_recent_def >= 3 and opp_def * 3 < n:
                return 'C'
        return 'C'

    return 'C'

