def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C'
    if n < 10:
        last = history[-1][1]
        if last == 'D':
            # brief forgiveness early to avoid locking into mutual defection
            if n >= 3 and history[-2][1] == 'D' and history[-3][1] == 'D':
                return 'D'
            return 'C'
        return 'C'

    opp_def = 0
    my_def = 0
    for m, o in history:
        if o == 'D':
            opp_def += 1
        if m == 'D':
            my_def += 1

    recent = history[-10:]
    recent_opp_def = 0
    recent_my_def = 0
    for m, o in recent:
        if o == 'D':
            recent_opp_def += 1
        if m == 'D':
            recent_my_def += 1

    last_me, last_opp = history[-1]

    # Endgame exploitation of reliable cooperators.
    if n >= 95:
        if opp_def * 3 < n:
            return 'D'
        if recent_opp_def >= 3:
            return 'D'
        return 'C'

    # If opponent is nearly always defecting, stop feeding them.
    if opp_def * 2 > n and recent_opp_def >= 5:
        return 'D'
    if opp_def * 3 > n * 2:
        return 'D'

    # Strong retaliate against sustained recent defection.
    if recent_opp_def >= 7:
        return 'D'

    # Opponent has been very cooperative: mostly cooperate, occasional probe.
    if recent_opp_def == 0:
        if n > 60 and opp_def == 0 and n < 90:
            return 'D'
        return 'C'

    # Recover quickly from mutual defection when opponent shows cooperation.
    if last_opp == 'C':
        if recent_opp_def <= 2:
            return 'C'
        if last_me == 'D' and rng.random() < 0.7:
            return 'C'
        if rng.random() < 0.5:
            return 'C'
        return 'D'

    # Opponent just defected: punish moderately but allow forgiveness.
    if recent_opp_def >= 4:
        return 'D'
    if recent_my_def > recent_opp_def + 2:
        return 'C'
    if last_me == 'D':
        if rng.random() < 0.6:
            return 'D'
        return 'C'
    if rng.random() < 0.35:
        return 'C'
    return 'D'

