    opp_coops = 0.0
    weight_sum = 0.0
    for i in range(n):
        w = 1.0 + (i / max(1, n - 1)) * 2.5
        weight_sum += w
        if history[i][1] == 'C':
            opp_coops += w
    coop_rate = opp_coops / weight_sum if weight_sum > 0 else 0.5

