    streak_defect = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            streak_defect += 1
        else:
            break

    streak_coop = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'C':
            streak_coop += 1
        else:
            break

