def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    my = [h[0] for h in history]
    op = [h[1] for h in history]

    # Endgame: DC=5 > CC=3, but only defect if opponent likely won't punish hard.
    remaining = 100 - n
    if remaining <= 0:
        return 'C'

    opD = op.count('D')
    myD = my.count('D')
    opC = n - opD

    # Perfect cooperator so far: keep cooperating, exploit only very late.
    if opD == 0:
        if remaining <= 1:
            return 'D'
        return 'C'

    # Perfect defector so far: defect but probe rarely to detect switches.
    if opC == 0:
        if n >= 3 and (n % 9 == 0) and rng.random() < 0.25:
            return 'C'
        return 'D'

    last_me, last_op = history[-1]

    # Recent window statistics
    w = 8 if n >= 8 else n
    recent_op = op[-w:]
    recent_my = my[-w:]
    r_opD = 0
    r_myD = 0
    for x in recent_op:
        if x == 'D':
            r_opD += 1
    for x in recent_my:
        if x == 'D':
            r_myD += 1

    # Detect mutual defection lock and break it occasionally
    if n >= 2 and my[-1] == 'D' and op[-1] == 'D' and my[-2] == 'D' and op[-2] == 'D':
        if n >= 3 and my[-3] == 'D' and op[-3] == 'D':
            # deep lock: probe cooperation
            return 'C'
        if rng.random() < 0.5:
            return 'C'

    # Strong retaliation for recent heavy defection by opponent
    if r_opD >= 4:
        if r_opD >= w - 1:
            return 'D'
        if rng.random() < 0.85:
            return 'D'
        return 'C'

    if r_opD >= 2:
        if last_op == 'D':
            if r_opD >= 3:
                return 'D'
            if rng.random() < 0.25:
                return 'C'
            return 'D'
        # Opponent cooperated last but recent mixed
        if opC * 2 >= n:
            return 'C'
        if rng.random() < 0.4:
            return 'C'
        return 'D'

    # Recent opponent mostly cooperative
    if r_opD <= 1:
        # If we've been defecting a lot relative to opponent, cooperate to repair
        if myD > opD + 2 and n >= 10:
            return 'C'
        # Late-game careful exploitation only against very cooperative opponent
        if remaining <= 3:
            if opD * 4 <= n and last_op == 'C':
                if remaining <= 1:
                    return 'D'
                if rng.random() < 0.4:
                    return 'D'
            return 'C'
        if last_op == 'D':
            # Forgive isolated defection if opponent historically nice
            if opD * 4 <= n and n >= 6:
                return 'C'
            return 'D'
        # Occasional probe against very cooperative long-run opponent
        if opD == 1 and n >= 6:
            return 'C'
        if n >= 12 and opD * 5 <= n and (n % 11 == 0) and rng.random() < 0.5:
            return 'D'
        return 'C'

    # Opponent globally aggressive but not extreme
    if opD * 2 > n:
        if last_op == 'D':
            return 'D'
        if r_myD >= 3:
            return 'C'
        if rng.random() < 0.3:
            return 'D'
        return 'C'

    # Mid-range opponent defection: tit-for-tat with forgiveness
    if last_op == 'D':
        if opD * 3 <= n and rng.random() < 0.2:
            return 'C'
        return 'D'
    if last_me == 'D' and dc_dc_check(history) if False else False:
        pass
    return 'C'


