def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C'
    if n == 2:
        return 'C'
    if n == 3:
        return 'C'
    if n == 4:
        return 'C'

    # Track opponent's defection pattern
    opp_defs = 0
    my_defs = 0
    opp_last_c = 0
    for i in range(n):
        m, o = history[i]
        if o == 'D':
            opp_defs += 1
        if m == 'D':
            my_defs += 1
        if o == 'C':
            opp_last_c = i

    # Count consecutive opponent defections at the end
    consec_opp_def = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            consec_opp_def += 1
        else:
            break

    # Count consecutive opponent cooperations at the end
    consec_opp_c = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'C':
            consec_opp_c += 1
        else:
            break

    # Count recent defections in last 10
    recent_opp_def = 0
    recent_my_def = 0
    start = n - 10
    if start < 0:
        start = 0
    for i in range(start, n):
        if history[i][1] == 'D':
            recent_opp_def += 1
        if history[i][0] == 'D':
            recent_my_def += 1

    opp_coop_rate = 1.0 - float(opp_defs) / float(n)

    # Defect hard against sustained defectors - no point cooperating
    if n >= 8 and recent_opp_def >= 8:
        return 'D'
    if n >= 15 and opp_defs > n * 0.75:
        return 'D'
    if n >= 20 and opp_defs > n * 0.6:
        return 'D'

    # Against sustained defection, never recover (matches four_D_TFT failure mode)
    if consec_opp_def >= 4 and n >= 8:
        # If opponent has shown they will keep defecting, stay defecting
        if n >= 15 and opp_coop_rate < 0.35:
            return 'D'
        if n >= 10 and recent_opp_def >= 7:
            return 'D'
        if rng.random() < 0.85:
            return 'D'
        return 'C'

    # Near endgame, exploit cooperative opponents
    if n >= 95:
        if opp_coop_rate > 0.5:
            return 'D'
        if consec_opp_c >= 2:
            return 'D'
        if opp_defs > n * 0.3:
            return 'D'
        return 'C'

    # Recovery: after being exploited, if opponent returns to cooperation, reciprocate
    if consec_opp_def == 1:
        if recent_opp_def >= 3:
            return 'D'
        if n >= 20 and opp_coop_rate > 0.6:
            if rng.random() < 0.4:
                return 'C'
        return 'D'

    if consec_opp_def == 2:
        if recent_opp_def >= 4:
            return 'D'
        if rng.random() < 0.25:
            return 'C'
        return 'D'

    if consec_opp_def == 3:
        if rng.random() < 0.15:
            return 'C'
        return 'D'

    # Opponent cooperated last round
    if consec_opp_c >= 5:
        # Long cooperation - mostly cooperate, occasional probe
        if n < 90 and rng.random() < 0.05:
            return 'D'
        return 'C'

    if opp_coop_rate > 0.85 and n >= 12:
        return 'C'

    if recent_opp_def >= 3 and n >= 12:
        if rng.random() < 0.7:
            return 'D'
        return 'C'

    if my_defs > opp_defs + 2 and consec_opp_c >= 1:
        return 'C'

    if rng.random() < 0.03:
        return 'D'
    return 'C'

